import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport '../../../core/providers/core_providers.dart';\nimport 'onboarding_screen.dart';\n// import '../../homework/views/grade_selection_screen.dart';\n// import '../../teacher/views/teacher_dashboard_screen.dart';\n\nclass SplashScreen extends ConsumerStatefulWidget {\n  const SplashScreen({Key? key}) : super(key: key);\n\n  @override\n  ConsumerState<SplashScreen> createState() => _SplashScreenState();\n}\n\nclass _SplashScreenState extends ConsumerState<SplashScreen> {\n  @override\n  void initState() {\n    super.initState();\n    _checkAuth();\n  }\n\n  Future<void> _checkAuth() async {\n    // Fake delay for splash screen\n    await Future.delayed(const Duration(seconds: 2));\n    \n    if (!mounted) return;\n\n    final localStorage = ref.read(localStorageServiceProvider);\n    final supabaseAuth = ref.read(supabaseClientProvider).auth;\n\n    // Check if Teacher is logged in\n    if (supabaseAuth.currentUser != null) {\n      // Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => const TeacherDashboardScreen()));\n      return;\n    }\n\n    // Check if Student has already set school code\n    final schoolCode = localStorage.getSchoolCode();\n    final studentName = localStorage.getStudentName();\n\n    if (schoolCode != null && schoolCode.isNotEmpty && studentName != null && studentName.isNotEmpty) {\n      // Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => const GradeSelectionScreen()));\n    } else {\n      Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => const OnboardingScreen()));\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return const Scaffold(\n      body: Center(\n        child: CircularProgressIndicator(),\n      ),\n    );\n  }\n}\n